// Space / Crypt dropdowns (2026-11-06). Martice: "prices on all niches that you can select from
// an additional dropdown depending on the mausoleum or niche section chosen based off whats
// currently available." Inventory = BW_SPACE_INV, generated by scripts/build-space-inventory.mjs
// from the live-MIS pull of 11/06/2026.
//
// Checks: every building with open spaces lists exactly its inventory; picking a space fills
// Price / Qty / Location and prices the quote line; switching building clears only what a pick
// filled (a typed price survives); flagged (cents) prices warn; buildings with nothing open say
// so; a saved quote reloads through the real load path with its space selected; a space that
// has since sold reloads as a disabled option with the saved price intact.
//
// Fake Firebase only — production is never contacted, and nothing here writes.
import { chromium } from 'playwright';
import fs from 'fs';
import { BASE } from './_base.mjs';
const FAKE = fs.readFileSync('tests/fake-firebase.js', 'utf8');
let pass = 0, fail = 0;
const ok = (n, c, x) => { if (c) { pass++; console.log('  PASS  ' + n); } else { fail++; console.log('  FAIL  ' + n + (x !== undefined ? '\n        ' + JSON.stringify(x) : '')); } };

const browser = await chromium.launch();
const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
await ctx.route(/gstatic\.com\/firebasejs/, r => r.abort());
const page = await ctx.newPage();
const errs = [];
page.on('pageerror', e => errs.push('pageerror: ' + e.message));
page.on('console', m => { if (m.type() === 'error' && !/Failed to load resource/.test(m.text())) errs.push(m.text().slice(0, 200)); });
await page.addInitScript(FAKE);
await page.addInitScript(`window.__fake.addAccount('t@bwquote.local','pw');`);
await page.goto(BASE, { waitUntil: 'load', timeout: 120000 });
await page.evaluate(() => _fbAuth.signInWithEmailAndPassword('t@bwquote.local', 'pw'));
await page.waitForFunction(() => window._fbQuotesReady === true, { timeout: 20000 });
await page.evaluate(() => { location.hash = '#cem-quote'; });
await page.waitForTimeout(500);

const vis = (id) => page.evaluate((i) => { const e = document.getElementById(i); return !!e && getComputedStyle(e).display !== 'none'; }, id);
const pickBuilding = (kind, name) => page.selectOption(kind === 'maus' ? '#qMausName' : '#qNicheName', name);
const pickSpace = (kind, key) => page.selectOption(kind === 'maus' ? '#qMausSpace' : '#qNicheSpace', key);
// cemUpdateD() is debounced; price synchronously before reading the lines.
const fields = () => page.evaluate(() => (cemUpdate(), {
  np: qNichePrice.value, nq: qNicheQty.value, nl: qNicheLocation.value, ns: qNicheSpace.value,
  mp: qMausPrice.value, mq: qMausQty.value, ml: qMausLocation.value, ms: qMausSpace.value,
  nNote: qNicheSpaceNote.textContent, mNote: qMausSpaceNote.textContent,
  lines: _cemLines.map(l => [l.label, l.amount]), total: _cemTotal,
}));

// ── 1. every building lists exactly its inventory ──────────────────────────────────
console.log('\n1. each building lists its open spaces');
const inv = await page.evaluate(() => BW_SPACE_INV);
ok('inventory is dated 2026-11-06', inv.asOf === '2026-11-06', inv.asOf);
for (const [kind, sel] of [['niche', 'qNicheName'], ['maus', 'qMausName']]) {
  const names = await page.evaluate((s) => [...document.getElementById(s).options].map(o => o.value), sel);
  for (const name of Object.keys(inv[kind])) {
    ok(`${kind}: "${name}" is an option in #${sel}`, names.includes(name));
    await pickBuilding(kind, name);
    const r = await page.evaluate((k) => {
      const s = document.getElementById(k === 'maus' ? 'qMausSpace' : 'qNicheSpace');
      return { n: [...s.options].filter(o => o.value).length, v: s.value };
    }, kind);
    ok(`${kind}: "${name}" lists ${inv[kind][name].units.length} spaces`, r.n === inv[kind][name].units.length && r.v === '', r);
  }
}
const totalUnits = Object.values(inv.niche).concat(Object.values(inv.maus)).reduce((a, b) => a + b.units.length, 0);
ok('1,088 priced spaces in all', totalUnits === 1088, totalUnits);
const allPos = Object.values(inv.niche).concat(Object.values(inv.maus)).every(b => b.units.every(u => u[3] > 0));
ok('no $0 space is offered', allPos);

// ── 2. picking a niche fills the fields and prices the line ───────────────────────
console.log('\n2. pick a Crystal niche');
await page.evaluate(() => resetCemQuote());
await pickBuilding('niche', 'Crystal Niches');
ok('Space row shows', await vis('qNicheSpaceRow'));
await pickSpace('niche', '1|G|9');
let f = await fields();
ok('price 3995, qty 1, location filled', f.np === '3995' && f.nq === '1' && f.nl === 'Wall 1, Level G, Space 9', f);
ok('quote line names building + location at $3,995', f.lines.some(([l, a]) => l === 'Crystal Niches — Wall 1, Level G, Space 9' && a === 3995), f.lines);
ok('ECF line $399.50', f.lines.some(([l, a]) => /^Niche ECF/.test(l) && Math.abs(a - 399.5) < 0.001), f.lines);
ok('note says MIS as of 11/06/2026', /MIS as of 11\/06\/2026/.test(f.nNote), f.nNote);
ok('glass arrangement row offered (Crystal = glass)', await vis('qNicheGlassRow') && !(await vis('qNicheGraniteRow')));

// ── 3. switching building clears what the pick filled ─────────────────────────────
console.log('\n3. switch building');
await pickBuilding('niche', 'Rock of Ages Columbarium');
f = await fields();
ok('price + location cleared, space reset', f.np === '' && f.nl === '' && f.ns === '', f);
ok('no niche line left on the quote', !f.lines.some(([l]) => /Crystal Niches/.test(l)), f.lines);

// typed price, no pick: survives a building change
await page.fill('#qNichePrice', '2500');
await page.fill('#qNicheLocation', 'hand typed');
await pickBuilding('niche', 'Terrace Garden Niches');
f = await fields();
ok('a hand-typed price and location survive a building change', f.np === '2500' && f.nl === 'hand typed', f);

// pick, then edit the price by hand: switching building keeps the edit
await pickSpace('niche', '1|E|1');
await page.fill('#qNichePrice', '11000');
await pickBuilding('niche', 'Crystal Niches');
f = await fields();
ok('a price edited after a pick is kept on building change', f.np === '11000', f);

// ── 4. flagged price warns ────────────────────────────────────────────────────────
console.log('\n4. flagged (cents) price');
await page.evaluate(() => resetCemQuote());
await pickBuilding('maus', 'Chapel of Memories');
const flagged = await page.evaluate(() => [...qMausSpace.options].find(o => /verify price/.test(o.textContent))?.value);
ok('COM has a flagged crypt in the list', !!flagged, flagged);
await pickSpace('maus', flagged);
f = await fields();
ok('flagged pick shows the half-price warning', /half-price entry/.test(f.mNote), f.mNote);
ok('A-183 is the flagged COM crypt at $12,497.50', flagged === '|A|183' && f.mp === '12497.5', [flagged, f.mp]);

// ── 5. building with nothing open ─────────────────────────────────────────────────
console.log('\n5. nothing open');
await pickBuilding('niche', 'Garden Court Niches');
ok('Space row hidden', !(await vis('qNicheSpaceRow')));
f = await fields();
ok('note says nothing priced is open', /No priced spaces open per MIS/.test(f.nNote), f.nNote);
await pickBuilding('niche', 'Mountain View Columbarium (Outside)');
f = await fields();
ok('MVC Outside: notes the 2 open with no MIS price', /2 open with no price set in MIS/.test(f.nNote), f.nNote);
await pickBuilding('niche', '__custom__');
ok('Custom: no row, no note', !(await vis('qNicheSpaceRow')) && !(await vis('qNicheSpaceNote')));
await pickBuilding('niche', '');
ok('Nothing selected: no row, no note', !(await vis('qNicheSpaceRow')) && !(await vis('qNicheSpaceNote')));

// ── 6. save → reload through the real load path ───────────────────────────────────
console.log('\n6. saved quote round-trip');
await page.evaluate(() => resetCemQuote());
await pickBuilding('niche', 'Mountain View Columbarium (New)');
const mvcKey = await page.evaluate(() => [...qNicheSpace.options].find(o => /^ISL-W\|/.test(o.value))?.value);
ok('MVC island west wall has an open niche', !!mvcKey, mvcKey);
await pickSpace('niche', mvcKey);
await pickBuilding('maus', 'Terrace Garden Mausoleum');
const tgmKey = await page.evaluate(() => [...qMausSpace.options].find(o => o.value)?.value);
await pickSpace('maus', tgmKey);
const before = await fields();
const state = await page.evaluate(() => captureCemState());
await page.evaluate((s) => { resetCemQuote(); _bwRestoreCemState(s); cemUpdate(); }, state);
f = await fields();
ok('niche space comes back selected with its price', f.ns === mvcKey && f.np === before.np && f.nl === before.nl, [before, f]);
ok('crypt comes back selected with its price', f.ms === tgmKey && f.mp === before.mp, [before.ms, f.ms]);
ok('reloaded total equals saved total', Math.abs(f.total - before.total) < 0.005, [before.total, f.total]);
// switching building after a reload still clears the reloaded pick
await pickBuilding('niche', 'Crystal Niches');
f = await fields();
ok('reloaded pick clears on building change', f.np === '' && f.nl === '', f);

// a space that has since sold
const sold = JSON.parse(JSON.stringify(state));
sold.fields.qNicheSpace = 'ISL-W|Z|99';
sold.fields.qNichePrice = '7000';
await page.evaluate((s) => { resetCemQuote(); _bwRestoreCemState(s); cemUpdate(); }, sold);
const r = await page.evaluate(() => ({ v: qNicheSpace.value, txt: qNicheSpace.selectedOptions[0]?.textContent, dis: qNicheSpace.selectedOptions[0]?.disabled, p: qNichePrice.value, t: _cemTotal }));
ok('a sold space reloads as a disabled "not on the current availability list" option', r.v === 'ISL-W|Z|99' && r.dis && /Not on the current availability list/.test(r.txt), r);
ok('its saved price is still on the quote', r.p === '7000', r);
// and old quotes (no space field at all) load exactly as before
const legacy = JSON.parse(JSON.stringify(state));
delete legacy.fields.qNicheSpace; delete legacy.fields.qMausSpace;
legacy.fields.qNichePrice = '4321';
await page.evaluate((s) => { resetCemQuote(); _bwRestoreCemState(s); cemUpdate(); }, legacy);
f = await fields();
ok('a pre-dropdown quote keeps its manual price', f.np === '4321' && f.ns === '', f);

// ── 6b. four-rights niches (Martice 2026-11-06) ────────────────────────────────────
console.log('\n6b. two-tier niches carry 4 rights');
await page.evaluate(() => resetCemQuote());
await pickBuilding('niche', 'Mountain View Columbarium (Inside)');
await pickSpace('niche', 'E-INT|ED|2');
f = await fields();
ok('E-INT ED-2: $32,995, location says 4 rights', f.np === '32995' && f.nl === 'Wall E-INT, Level ED, Space 2 (4 rights)', f);
ok('quote line carries "(4 rights)"', f.lines.some(([l]) => /Level ED, Space 2 \(4 rights\)$/.test(l)), f.lines);
const fourR = await page.evaluate(() => {
  const all = [];
  for (const b of Object.values(BW_SPACE_INV.niche)) for (const u of b.units) if (u[5]) all.push(u.slice(0, 3).join('|') + '=' + u[5]);
  return all.sort();
});
ok('exactly the 6 two-tier MVC niches are 4-rights', JSON.stringify(fourR) === JSON.stringify(['E-INT|ED|2=4', 'E-INT|ED|3=4', 'ISL-E|D/E|1=4', 'ISL-E|D/E|2=4', 'ISL-W|D/E|1=4', 'ISL-W|D/E|2=4']), fourR);
await pickBuilding('niche', 'Mountain View Columbarium (New)');
const islTxt = await page.evaluate(() => [...qNicheSpace.options].find(o => o.value === 'ISL-W|D/E|1')?.textContent);
ok('island D/E double lists as 4 rights at $42,000', /Level D\/E, Space 1 \(4 rights\) — \$42,000/.test(islTxt || ''), islTxt);

// ── 6c. operator price override ───────────────────────────────────────────────────
console.log('\n6c. ROAC D-INT D-5 = $14,995 (ruling 2026-08-01, reaffirmed 2026-11-06)');
const d5 = await page.evaluate(() => BW_SPACE_INV.niche['Rock of Ages Columbarium'].units.find(u => u[0] === 'D-INT' && u[1] === 'D' && u[2] === '5'));
ok('D-INT D-5 lists at $14,995, not MIS $16,495', d5 && d5[3] === 14995, d5);

// ── 7. reset ──────────────────────────────────────────────────────────────────────
await page.evaluate(() => resetCemQuote());
ok('New quote hides both space rows', !(await vis('qNicheSpaceRow')) && !(await vis('qMausSpaceRow')));

ok('no page errors', errs.length === 0, errs);
await browser.close();
console.log(`\n${pass} passed, ${fail} failed`);
process.exit(fail ? 1 : 0);
